"""Generate the source-hashed CPU-only B19618 preflight stdin payload."""
import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def build():
    path = ROOT / 'scripts/pose_b19618_preflight.py'
    source = path.read_text()
    delimiter = 'WEARUSFM_B19618_PREFLIGHT_SOURCE'
    if not source.endswith('\n') or '\n' + delimiter + '\n' in source:
        raise ValueError('invalid embedded source delimiter/newline')
    digest = hashlib.sha256(source.encode()).hexdigest()
    prefix = '''#!/bin/bash
# Generated by scripts/build_pose_b19618_preflight_payload.py.
#SBATCH -A IscrB_WearUsFM
#SBATCH -p lrd_all_serial
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=2
#SBATCH --mem=16G
#SBATCH --time=00:10:00
#SBATCH -o /leonardo_work/IscrB_WearUsFM/wearusfm_runs/logs/pose_b19618_preflight_%j.out
#SBATCH -e /leonardo_work/IscrB_WearUsFM/wearusfm_runs/logs/pose_b19618_preflight_%j.out
set -euo pipefail
: "${CODE_DIR:?}" "${EXPECTED_SHA:?}" "${WRAPPER_SHA256:?}" "${WORK:?}"
[ "$EXPECTED_SHA" = 24139ab901c052357a46a65bc20466f2eb1e8358 ] || exit 2
source "$CODE_DIR/scripts/slurm/lib_code_dir.sh"
code_dir_setup
module purge
module load profile/deeplrn
module load cineca-ai/4.3.0
source "$WORK/venv_wearusfm/bin/activate"
export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1 PYTHONDONTWRITEBYTECODE=1
B19618_PREFLIGHT_TMP=$(mktemp -d "${TMPDIR:-/tmp}/wearusfm-b19618-preflight.XXXXXX")
trap 'rm -f -- "$B19618_PREFLIGHT_TMP/pose_b19618_preflight.py"; rmdir -- "$B19618_PREFLIGHT_TMP"' EXIT
'''
    return (prefix + f'cat > "$B19618_PREFLIGHT_TMP/pose_b19618_preflight.py" <<\'{delimiter}\'\n'
            + source + delimiter + '\n'
            + f'python3 "$B19618_PREFLIGHT_TMP/pose_b19618_preflight.py" --source-sha256 {digest} --wrapper-sha256 "$WRAPPER_SHA256"\n').encode()


if __name__ == '__main__':
    payload = build()
    target = ROOT / 'scripts/slurm/pose_b19618_preflight.sbatch'
    target.write_bytes(payload)
    print(f'{target.name}: {hashlib.sha256(payload).hexdigest()}')
